/**
 * Bring the Traveller Ship Designer's engine into this project, and work out
 * the crew of every ship it ships with. CharSpec 12.8.
 *
 *   node scripts/vendor-ship-designer.mjs [path to Traveller-Ship-Design]
 *
 * Writes two generated files, both committed so the build needs nothing but
 * this repository:
 *   src/vendor/ship-designer.js  the designer's sheet() and parse(), bundled
 *   src/rules/ship-designs.json  name, tonnage and crew of each catalogue ship
 *
 * Run it again when the designer's crew rules or catalogue change.
 */
import { build } from "esbuild";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const designer = resolve(process.argv[2] ?? "../Traveller-Ship-Design");
const here = resolve(".");
const out = resolve(here, "src/vendor/ship-designer.js");
const version = JSON.parse(readFileSync(resolve(designer, "package.json"), "utf8")).version;

await build({
  stdin: {
    contents: [
      `export { sheet } from ${JSON.stringify(resolve(designer, "src/engine/sheet.ts"))};`,
      `export { parse } from ${JSON.stringify(resolve(designer, "src/io/save.ts"))};`,
      `export { SCOUT_COURIER } from ${JSON.stringify(resolve(designer, "src/fixtures/scoutCourier.ts"))};`,
      `export { FREE_TRADER } from ${JSON.stringify(resolve(designer, "src/fixtures/freeTrader.ts"))};`,
      `export { PATROL_CORVETTE } from ${JSON.stringify(resolve(designer, "src/fixtures/patrolCorvette.ts"))};`,
      `export { DESTROYER_ESCORT } from ${JSON.stringify(resolve(designer, "src/fixtures/destroyerEscort.ts"))};`,
    ].join("\n"),
    resolveDir: designer,
    loader: "ts",
  },
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2022",
  outfile: out,
  banner: {
    js: `// Generated by scripts/vendor-ship-designer.mjs from Traveller Ship Designer ${version}\n// (https://github.com/Doomy66/Traveller-Ship-Design, PolyForm Noncommercial). Do not edit.`,
  },
  logLevel: "warning",
});

const engine = await import(pathToFileURL(out).href + `?t=${Date.now()}`);

/** The designer's crew roles, as this project's posts. */
const POSTS = {
  captain: "captain",
  pilot: "pilot",
  astrogator: "astrogator",
  engineer: "engineer",
  maintenance: "maintenance",
  gunner: "gunner",
  steward: "steward",
  administrator: "administrator",
  sensorOperator: "sensor-operator",
  medic: "medic",
  officer: "officer",
};

function crewOf(design) {
  const counts = {};
  for (const c of engine.sheet(design).crew) {
    const post = POSTS[c.role];
    if (!post) throw new Error(`${design.name}: no post for crew role ${c.role}`);
    counts[post] = (counts[post] ?? 0) + c.count;
  }
  return counts;
}

const ships = [];
const add = (design, group) => ships.push({ name: design.name, tons: design.hull.tons, military: design.military === true, group, counts: crewOf(design) });
for (const d of [engine.SCOUT_COURIER, engine.FREE_TRADER, engine.PATROL_CORVETTE, engine.DESTROYER_ESCORT]) add(d, "High Guard 2022");
const catalogue = resolve(designer, "src/catalogue");
for (const f of readdirSync(catalogue).filter((x) => x.endsWith(".ship"))) {
  const d = engine.parse(readFileSync(resolve(catalogue, f), "utf8"));
  if (!d) throw new Error(`${f} is not a ship design`);
  add(d, "Ship Designer catalogue");
}
ships.sort((a, b) => a.tons - b.tons || a.name.localeCompare(b.name));
writeFileSync(resolve(here, "src/rules/ship-designs.json"), JSON.stringify({ designer: version, ships }, null, 1) + "\n");
console.log(`Bundled Ship Designer ${version}; crews for ${ships.length} ships.`);
